debug_text.text:
'[SES][M5 WORK] Ignored stale or mismatched work completion. mode=%s token=%s salvage=%s weld=%s'.[
            $Mode,
            $Token,
            @global.$SES_Salvage_Work_Token,
            @global.$SES_Weld_Work_Token
          ]

'[SES][M5 UIX] Native planner action handled. action=%s index=%s context=%s'.[
          $Action,
          $Index,
          @global.$SES_M5_Native_UI_Context
        ]

'[SES][M5 UIX] Experimental shell requested current planner fallback. kind=%s enabled=%s'.[
          event.param3,
          @global.$SES_M5_Native_Planners_Experimental_Enabled
        ]

'[SES][ECON] Black Market economy v41 initialized for v310 production. First successful salvage schedules the global announcement after a randomized 2-4 minute delay, then unlocks the shady-guy shop option. Player sales pay 60 percent; all dealer stock costs 120 percent. Generated stock uses 4-10 rows and the developer-gated fast rotation switch selects 1-2 minute refreshes instead of the production 3-5 hour window. No gameplay or debug system requires an experimental flag. forcegeneration=%s fastrotation=%s'.[
          @global.$SES_Black_Market_Debug_Force_Rotation_Generation,
          @global.$SES_Black_Market_Debug_Fast_Rotation_Enabled
        ]

'[SES][ECON] Galaxy Network high-priority black-market GalNet article written via write_incoming_message. flag=%s'.[
            global.$SES_Black_Market_Special_Stock_Message_V4
          ]

'[SES][ECON] Black Market migration roll actor=%s, station=%s, salvagerroll=%s, welderroll=%s, beamcatalystroll=%s, bondingcatalystroll=%s'.[
                $ShadyGuy,
                $ShadyGuyStation,
                @global.$SES_Economy_ShadyGuy_Stock_Rolls.{$ShadyGuy}.$salvagerroll,
                @global.$SES_Economy_ShadyGuy_Stock_Rolls.{$ShadyGuy}.$welderroll,
                @global.$SES_Economy_ShadyGuy_Stock_Rolls.{$ShadyGuy}.$beamcatalystroll,
                @global.$SES_Economy_ShadyGuy_Stock_Rolls.{$ShadyGuy}.$bondingcatalystroll
              ]

'[SES][ECON] v249 catalyst-only Black Market migration roll actor=%s, station=%s, beamcatalystroll=%s, bondingcatalystroll=%s'.[
                $ShadyGuy,
                $ShadyGuyStation,
                @global.$SES_Economy_ShadyGuy_Stock_Rolls.{$ShadyGuy}.$beamcatalystroll,
                @global.$SES_Economy_ShadyGuy_Stock_Rolls.{$ShadyGuy}.$bondingcatalystroll
              ]

'[SES][TOOLS] Trimmed duplicate Avarice Beam Regulators after inventory add. eventamount=%s, before=%s, after=%s, removed=%s'.[
            @event.param.{ware.ses_equipment_salvager},
            $ToolCapBefore,
            player.entity.inventory.{ware.ses_equipment_salvager}.count,
            $ToolCapBefore - player.entity.inventory.{ware.ses_equipment_salvager}.count
          ]

'[SES][TOOLS] Trimmed duplicate Avarice Bonding Regulators after inventory add. eventamount=%s, before=%s, after=%s, removed=%s'.[
            @event.param.{ware.ses_equipment_welder},
            $ToolCapBefore,
            player.entity.inventory.{ware.ses_equipment_welder}.count,
            $ToolCapBefore - player.entity.inventory.{ware.ses_equipment_welder}.count
          ]

'[SES][MODE UI] Publishing authoritative SES tool mode to Lua on UI request. request=%s, mode=%s, controlled=%s'.[
          event.param3,
          global.$SES_Tool_Mode,
          @player.controlled
        ]

'[SES][MODE] Production tool-mode bridge initialized for v313. currentmode=%s. Direct SES tool hits require the selected mode, Hand Laser, matching tool inventory, and spacesuit control. Bomb Launcher ammunition is intentionally untouched.'.[
          @global.$SES_Tool_Mode
        ]

'[SES][INV UI] PlayerInfo XPL registered SES.SalvageInventory event listener. param=%s'.[
          event.param3
        ]

'[SES][INV UI] PlayerInfo XPL failed to register SES.SalvageInventory event listener. param=%s'.[
          event.param3
        ]

'[SES][INV UI] PlayerInfo XPL received salvage inventory state. param=%s'.[
          event.param3
        ]

'[SES][INV UI] Salvage Inventory Lua reported loaded through ui.xml/UIX path. version=%s'.[
          event.param3
        ]

'[SES][INV UI] Salvage Inventory UI requested ledger publish. request=%s'.[
          event.param3
        ]

write_to_logbook.text:
'Dropped one salvaged equipment item into a secure lockbox ahead of the player.\nCategory: %s\nWare: %s\nMacro: %s\nRemaining: %s'.[
                    if @$InventoryEntry.$category then $InventoryEntry.$category else 'legacy',
                    $InventoryEntry.$wareid,
                    $InventoryEntry.$macro,
                    $DropCountAfter
                  ]

debug_text.text:
'[SES][SHOP UIX] Black Market UserQuestionMenu trader Lua loaded. version=%s'.[
          event.param3
        ]

'[SES][SHOP UIX] Black Market UserQuestionMenu Lua file loaded through ui.xml. version=%s'.[
          event.param3
        ]

'[SES][SHOP UIX] Black Market UserQuestionMenu callback registration missed UserQuestionMenu. reason=%s'.[
          event.param3
        ]

'[SES][SHOP UIX] Black Market UserQuestionMenu trader opened successfully. param=%s'.[
          event.param3
        ]

'[SES][SHOP UI] Black Market native-style trader requested ledger publish. request=%s'.[
          event.param3
        ]

raise_lua_event.param:
'player;%s;%s;%s;%s;%s'.[
                $InventoryIndex,
                if @$InventoryEntry.$category then $InventoryEntry.$category else 'legacy',
                $InventoryEntry.$wareid,
                if @$InventoryEntry.$macro then $InventoryEntry.$macro else '',
                $InventoryEntry.$count
              ]

'stock;%s;%s;%s;%s;%s'.[
                $StockIndex,
                if @$StockEntry.$category then $StockEntry.$category else 'legacy',
                $StockEntry.$wareid,
                if @$StockEntry.$macro then $StockEntry.$macro else '',
                $StockEntry.$count
              ]

debug_text.text:
'[SES][SHOP UI] Reconstructed production transaction-scoped global trade rows from barter blackboard. playerkeys=%s, storekeys=%s, selectedrows=%s, selectedquantity=%s, traderows=%s marker=v310_production'.[
            if typeof $BarterPlayerInventory == datatype.table then $BarterPlayerInventory.keys.count else 0,
            if typeof $BarterStoreInventory == datatype.table then $BarterStoreInventory.keys.count else 0,
            $BarterSelectedRows,
            $BarterSelectedQuantity,
            global.$SES_Black_Market_Runtime_TradeRows.count
          ]

'[SES][SHOP UIX] UserQuestionMenu Black Market debug: %s'.[
          event.param3
        ]

'[SES][SHOP UIX] UserQuestionMenu Black Market trade menu closed. reason=%s'.[
          @event.param3.$reason
        ]

signal_cue_instantly.param:
table[$col = 1, $colSpan = 6, $text = 'Fence recovered ship equipment through this Black Market contact. Offers pay 60%% of average ware value. The sale debits the salvaged-parts ledger only after the credit reward is issued.\nContact: %s\nStatus: %s'.[
            if $ShopActor.exists then $ShopActor.knownname else 'Unknown Black Market contact',
            if $ShopActorOK then 'Ready' else 'Black Market trades are not currently available'
          ], $wordwrap = true]

